1	import { types as nodeTypes } from 'node:util';
2	
3	const NODE_TYPES = new Set(['trigger', 'form', 'condition', 'action', 'end']);
4	const FIELD_TYPES = new Set(['string', 'number', 'integer', 'boolean']);
5	const FORBIDDEN_SEGMENTS = new Set(['__proto__', 'prototype', 'constructor']);
6	const STRING_BOUNDS = new Set(['minLength', 'maxLength']);
7	const NUMBER_BOUNDS = new Set(['min', 'max']);
8	
9	function assertPlainObject(value, label) {
10	  if (!value || typeof value !== 'object' || Array.isArray(value)) {
11	    throw new TypeError(`${label} must be an object`);
12	  }
13	}
14	
15	function isUsableObject(value) {
16	  return value !== null && typeof value === 'object' && !Array.isArray(value);
17	}
18	
19	function valueMatchesType(value, type) {
20	  if (type === 'string') return typeof value === 'string';
21	  if (type === 'boolean') return typeof value === 'boolean';
22	  if (typeof value !== 'number') return false;
23	  if (type === 'number') return Number.isFinite(value);
24	  return Number.isInteger(value);
25	}
26	
27	function valueSatisfiesBounds(value, spec) {
28	  if (spec.type === 'string') {
29	    const length = [...value].length;
30	    if (spec.minLength !== undefined && length < spec.minLength) return false;
31	    if (spec.maxLength !== undefined && length > spec.maxLength) return false;
32	  } else if (spec.type === 'number' || spec.type === 'integer') {
33	    if (spec.min !== undefined && value < spec.min) return false;
34	    if (spec.max !== undefined && value > spec.max) return false;
35	  }
36	  return true;
37	}
38	
39	function compileFormSchema(node) {
40	  if (!Object.hasOwn(node, 'schema') || node.schema === undefined) return null;
41	  if (!isUsableObject(node.schema)) {
42	    throw new Error(`form node ${node.id}: schema must be an object`);
43	  }
44	  if (!Array.isArray(node.schema.fields)) {
45	    throw new Error(`form node ${node.id}: schema.fields must be an array`);
46	  }
47	
48	  const seenSegments = [];
49	  const compiled = [];
50	  node.schema.fields.forEach((field, index) => {
51	    const label = `form node ${node.id} field ${field && isUsableObject(field) && typeof field.path === 'string' && field.path ? field.path : `#${index}`}`;
52	    if (!isUsableObject(field)) {
53	      throw new Error(`${label}: field must be an object`);
54	    }
55	    if (typeof field.path !== 'string' || field.path.length === 0) {
56	      throw new Error(`form node ${node.id} field #${index}: path must be a non-empty string`);
57	    }
58	    const segments = field.path.split('.');
59	    if (segments.some(part => part.length === 0)) {
60	      throw new Error(`${label}: path must not contain empty segments`);
61	    }
62	    if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
63	      throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
64	    }
65	    for (const previous of seenSegments) {
66	      const shared = Math.min(previous.length, segments.length);
67	      let prefix = true;
68	      for (let i = 0; i < shared; i += 1) {
69	        if (previous[i] !== segments[i]) { prefix = false; break; }
70	      }
71	      if (prefix && previous.length === segments.length) {
72	        throw new Error(`${label}: duplicate field path`);
73	      }
74	      if (prefix) {
75	        throw new Error(`${label}: field paths must not be parent and child of each other`);
76	      }
77	    }
78	    seenSegments.push(segments);
79	
80	    if (!FIELD_TYPES.has(field.type)) {
81	      throw new Error(`${label}: unknown field type ${field.type}`);
82	    }
83	    const spec = { path: field.path, segments, type: field.type, required: false, hasDefault: false };
84	
85	    if (Object.hasOwn(field, 'required')) {
86	      if (typeof field.required !== 'boolean') {
87	        throw new Error(`${label}: required must be a boolean`);
88	      }
89	      spec.required = field.required;
90	    }
91	
92	    const applicableBounds = field.type === 'string' ? STRING_BOUNDS
93	      : (field.type === 'number' || field.type === 'integer') ? NUMBER_BOUNDS
94	      : new Set();
95	    for (const bound of ['minLength', 'maxLength', 'min', 'max']) {
96	      if (!Object.hasOwn(field, bound) || field[bound] === undefined) continue;
97	      if (!applicableBounds.has(bound)) {
98	        throw new Error(`${label}: ${bound} does not apply to ${field.type} fields`);
99	      }
100	      const value = field[bound];
101	      if (field.type === 'string') {
102	        if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
103	          throw new Error(`${label}: ${bound} must be a non-negative integer`);
104	        }
105	      } else if (typeof value !== 'number' || !Number.isFinite(value)) {
106	        throw new Error(`${label}: ${bound} must be a finite number`);
107	      }
108	      spec[bound] = value;
109	    }
110	    if (spec.minLength !== undefined && spec.maxLength !== undefined && spec.minLength > spec.maxLength) {
111	      throw new Error(`${label}: minLength must not be greater than maxLength`);
112	    }
113	    if (spec.min !== undefined && spec.max !== undefined && spec.min > spec.max) {
114	      throw new Error(`${label}: min must not be greater than max`);
115	    }
116	
117	    if (Object.hasOwn(field, 'default') && field.default !== undefined) {
118	      const fallback = field.default;
119	      if (!valueMatchesType(fallback, spec.type)) {
120	        throw new Error(`${label}: default value does not match field type ${spec.type}`);
121	      }
122	      if (!valueSatisfiesBounds(fallback, spec)) {
123	        throw new Error(`${label}: default value violates field constraints`);
124	      }
125	      spec.hasDefault = true;
126	      spec.default = fallback;
127	    }
128	
129	    compiled.push(spec);
130	  });
131	
132	  return compiled;
133	}
134	
135	const MAX_CONDITION_DEPTH = 32;
136	
137	function parsePathSegments(path, label) {
138	  if (typeof path !== 'string' || path.length === 0) {
139	    throw new Error(`${label}: path must be a non-empty string`);
140	  }
141	  const segments = path.split('.');
142	  if (segments.some(part => part.length === 0)) {
143	    throw new Error(`${label}: path must not contain empty segments`);
144	  }
145	  if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
146	    throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
147	  }
148	  return segments;
149	}
150	
151	function isComparableConstant(value) {
152	  return value === null || typeof value === 'string' || typeof value === 'boolean'
153	    || (typeof value === 'number' && Number.isFinite(value));
154	}
155	
156	function toComparableNumber(value) {
157	  // Objects and arrays never participate in numeric comparison, even though
158	  // Number([]) === 0; everything else uses JS numeric conversion.
159	  if (value !== null && typeof value === 'object') return null;
160	  const converted = Number(value);
161	  return Number.isFinite(converted) ? converted : null;
162	}
163	
164	// Validates an output reference of the shape
165	// `{ "nodeId": "risk-check", "path": "risk.score" }` (path optional). The
166	// reference itself must be a non-array object, nodeId must name an action
167	// node in this definition (matched as a whole string — dots are literal),
168	// and path, when present, follows the same segment rules as input paths.
169	function compileOutputReference(ref, nodes, label) {
170	  if (!isUsableObject(ref)) {
171	    throw new Error(`${label}: output reference must be a non-array object`);
172	  }
173	  if (typeof ref.nodeId !== 'string' || ref.nodeId.length === 0) {
174	    throw new Error(`${label}: nodeId must be a non-empty string naming an action node`);
175	  }
176	  const target = nodes.get(ref.nodeId);
177	  if (!target) {
178	    throw new Error(`${label}: nodeId "${ref.nodeId}" does not name a node in this workflow`);
179	  }
180	  if (target.type !== 'action') {
181	    throw new Error(`${label}: nodeId "${ref.nodeId}" must name an action node`);
182	  }
183	  let segments = [];
184	  if (Object.hasOwn(ref, 'path')) {
185	    segments = parsePathSegments(ref.path, `${label} path`);
186	  }
187	  return { nodeId: ref.nodeId, segments };
188	}
189	
190	// Walks every condition node (including untaken branches) and turns it into a
191	// pre-validated, pre-resolved structure. Any malformed condition throws with a
192	// node id and a `$`-style child position, before the workflow can execute.
193	function compileCondition(condition, nodes, nodeId, position = '$', depth = 1) {
194	  if (depth > MAX_CONDITION_DEPTH) {
195	    throw new Error(`condition node ${nodeId} at ${position}: conditions must not be nested deeper than ${MAX_CONDITION_DEPTH} levels`);
196	  }
197	  if (!isUsableObject(condition)) {
198	    throw new Error(`condition node ${nodeId} at ${position}: condition must be an object`);
199	  }
200	
201	  const comboKeys = [];
202	  if (Object.hasOwn(condition, 'all')) comboKeys.push('all');
203	  if (Object.hasOwn(condition, 'any')) comboKeys.push('any');
204	  if (Object.hasOwn(condition, 'not')) comboKeys.push('not');
205	  if (comboKeys.length > 1) {
206	    throw new Error(`condition node ${nodeId} at ${position}: condition must use only one of all, any or not`);
207	  }
208	
209	  const comparisonKeys = ['field', 'outputField', 'operator', 'value', 'valueField', 'valueOutputField'];
210	  const presentComparisonKeys = comparisonKeys.filter(key => Object.hasOwn(condition, key));
211	
212	  if (comboKeys.length === 1) {
213	    if (presentComparisonKeys.length > 0) {
214	      throw new Error(`condition node ${nodeId} at ${position}: ${comboKeys[0]} condition must not mix in field, outputField, operator, value, valueField or valueOutputField`);
215	    }
216	    const key = comboKeys[0];
217	    if (key === 'not') {
218	      return { kind: 'not', child: compileCondition(condition.not, nodes, nodeId, `${position}.not`, depth + 1) };
219	    }
220	    if (!Array.isArray(condition[key])) {
221	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must be an array of conditions`);
222	    }
223	    if (condition[key].length === 0) {
224	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must not be empty`);
225	    }
226	    return {
227	      kind: key,
228	      children: condition[key].map((child, index) =>
229	        compileCondition(child, nodes, nodeId, `${position}.${key}[${index}]`, depth + 1)),
230	    };
231	  }
232	
233	  const where = `condition node ${nodeId} at ${position}`;
234	  const hasField = Object.hasOwn(condition, 'field');
235	  const hasOutputField = Object.hasOwn(condition, 'outputField');
236	  if ((!hasField && !hasOutputField) || !Object.hasOwn(condition, 'operator')) {
237	    throw new Error(`${where}: condition must be a comparison (field and operator) or a compound (all, any or not)`);
238	  }
239	  if (hasField && hasOutputField) {
240	    throw new Error(`${where}: condition must specify exactly one of field or outputField`);
241	  }
242	
243	  if (!['eq', 'gte', 'lte', 'exists'].includes(condition.operator)) {
244	    throw new Error(`${where}: unknown condition operator: ${condition.operator}`);
245	  }
246	
247	  let left;
248	  if (hasField) {
249	    left = { kind: 'input', label: 'field', segments: parsePathSegments(condition.field, `${where} field`) };
250	  } else {
251	    left = {
252	      kind: 'output', label: 'outputField',
253	      ref: compileOutputReference(condition.outputField, nodes, `${where} outputField`),
254	    };
255	  }
256	
257	  if (condition.operator === 'exists') {
258	    const unexpected = presentComparisonKeys.filter(key =>
259	      key === 'value' || key === 'valueField' || key === 'valueOutputField');
260	    if (unexpected.length > 0) {
261	      throw new Error(`${where}: exists only takes field and operator (outputField may name the left side)`);
262	    }
263	    return { kind: 'comparison', operator: 'exists', left };
264	  }
265	
266	  const hasValue = Object.hasOwn(condition, 'value');
267	  const hasValueField = Object.hasOwn(condition, 'valueField');
268	  const hasValueOutput = Object.hasOwn(condition, 'valueOutputField');
269	  const rightCount = [hasValue, hasValueField, hasValueOutput].filter(Boolean).length;
270	  if (rightCount !== 1) {
271	    throw new Error(`${where}: condition must specify exactly one of value or valueField (or valueOutputField)`);
272	  }
273	
274	  let right;
275	  if (hasValue) {
276	    if (!isComparableConstant(condition.value)) {
277	      throw new Error(`${where}: value must be a string, finite number, boolean or null`);
278	    }
279	    right = { kind: 'constant', label: 'value', value: condition.value };
280	    if (condition.operator !== 'eq') {
281	      const numericValue = toComparableNumber(condition.value);
282	      if (numericValue === null) {
283	        throw new Error(`${where}: value for ${condition.operator} must convert to a finite number`);
284	      }
285	      right.numericValue = numericValue;
286	    }
287	  } else if (hasValueField) {
288	    if (typeof condition.valueField !== 'string') {
289	      throw new Error(`${where} valueField: path must be a non-empty string`);
290	    }
291	    right = {
292	      kind: 'input', label: 'valueField',
293	      segments: parsePathSegments(condition.valueField, `${where} valueField`),
294	    };
295	  } else {
296	    right = {
297	      kind: 'output', label: 'valueOutputField',
298	      ref: compileOutputReference(condition.valueOutputField, nodes, `${where} valueOutputField`),
299	    };
300	  }
301	
302	  return { kind: 'comparison', operator: condition.operator, left, right };
303	}
304	
305	const formSchemas = new WeakMap();
306	const compiledConditions = new WeakMap();
307	const successorTargets = new WeakMap();
308	const nodeDependencies = new WeakMap();
309	const actionBindings = new WeakMap();
310	
311	const RETRY_FIELDS = ['attempts', 'initialDelayMs', 'backoffFactor', 'maxDelayMs'];
312	const DEFAULT_RETRY = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
313	
314	function isIntegerIn(value, min, max) {
315	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
316	}
317	
318	// A retry block is either absent (one attempt, no waiting) or present with all
319	// four parameters together, each within the same ranges the engine enforces
320	// for business action retries and compensation retries alike.
321	function compileRetry(config, label) {
322	  if (!isUsableObject(config)) {
323	    throw new Error(`${label}: retry must be an object`);
324	  }
325	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
326	  if (missing.length > 0) {
327	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
328	  }
329	  if (!isIntegerIn(config.attempts, 1, 10)) {
330	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
331	  }
332	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
333	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
334	  }
335	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
336	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
337	  }
338	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
339	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
340	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
341	  }
342	  if (config.maxDelayMs < config.initialDelayMs) {
343	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
344	  }
345	  return {
346	    attempts: config.attempts,
347	    initialDelayMs: config.initialDelayMs,
348	    backoffFactor: config.backoffFactor,
349	    maxDelayMs: config.maxDelayMs,
350	  };
351	}
352	
353	// An action node either keeps the legacy `message` behavior, names a business
354	// operation the caller supplies at run time, and/or declares a compensation
355	// operation that undoes its business effect. Both retry blocks are optional
356	// and, absent, mean exactly one attempt with no waiting.
357	function compileAction(node) {
358	  let name = null;
359	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
360	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
361	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
362	    }
363	    name = node.operation;
364	  }
365	
366	  let retry = { ...DEFAULT_RETRY };
367	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
368	    if (!name) {
369	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
370	    }
371	    retry = compileRetry(node.retry, `action node ${node.id}`);
372	  }
373	
374	  let compensation = null;
375	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
376	    if (!isUsableObject(node.compensation)) {
377	      throw new Error(`action node ${node.id}: compensation must be an object`);
378	    }
379	    if (!name) {
380	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
381	    }
382	    const config = node.compensation;
383	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
384	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
385	    }
386	    let compRetry = { ...DEFAULT_RETRY };
387	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
388	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
389	    }
390	    compensation = { name: config.operation, retry: compRetry };
391	  }
392	
393	  // A legacy message action (no operation) may carry a structured object or
394	  // array as its message, and the output it saves is snapshotted per run. A
395	  // value the structured clone algorithm cannot deliver — a bare function or
396	  // a function nested inside an object/array — is a definition error naming
397	  // the action and the reason, for every message action including actions on
398	  // untaken branches and entry-unreachable ones. An action that names an
399	  // operation ignores its message entirely, so an unused uncloneable message
400	  // is never rejected for it.
401	  //
402	  // A value that clones but whose clone retains shared memory is rejected for
403	  // the same reason the run input and operation return values are: cloning a
404	  // SharedArrayBuffer (or a typed array / DataView backed by one) "succeeds"
405	  // while the clone keeps sharing the underlying bytes, so the independent
406	  // output copy the action promises — including against the definition's own
407	  // message, which the engine clones again at execution time — could not be
408	  // guaranteed. The check therefore runs on the cloned value with the same
409	  // clone-shaped traversal (containsSharedMemory): shared memory placed only
410	  // where cloning drops it (an attached property of a Date/RegExp, a
411	  // non-enumerable property, an Error own property other than cause) is
412	  // discarded with that property and never condemns the message.
413	  if (name === null && Object.hasOwn(node, 'message') && node.message !== undefined) {
414	    let cloned;
415	    try {
416	      cloned = structuredClone(node.message);
417	    } catch {
418	      throw new Error(`action node ${node.id}: message must be a structured-cloneable value (objects and arrays must not contain functions)`);
419	    }
420	    if (containsSharedMemory(cloned)) {
421	      throw new Error(`action node ${node.id}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`);
422	    }
423	  }
424	
425	  return { name, retry, compensation };
426	}
427	
428	// An end node's result is delivered to the caller verbatim for primitives
429	// (null, undefined, strings, numbers, booleans), but an object or array result
430	// must be structured-clonable: the engine snapshots it independently both at
431	// validation time and again when the end node actually runs. A function (or a
432	// symbol, getter-built object the clone algorithm rejects, etc.) nested in a
433	// result object/array is a definition error naming the end node and reason;
434	// bare function results cannot be delivered through JSON-style results either.
435	function compileEndResult(node) {
436	  if (!Object.hasOwn(node, 'result') || node.result === undefined) return;
437	  try {
438	    structuredClone(node.result);
439	  } catch {
440	    throw new Error(`end node ${node.id}: result must be a structured-cloneable value (objects and arrays must not contain functions)`);
441	  }
442	}
443	
444	// Resolves the outgoing edges of a node. Trigger, form and action nodes may
445	// name a single successor or a non-empty, duplicate-free array of successors;
446	// conditions keep their then/else pair and end nodes have none.
447	function normalizeSuccessors(node, nodes) {
448	  if (node.type === 'end') return [];
449	  if (node.type === 'condition') {
450	    for (const destination of [node.then, node.else]) {
451	      if (typeof destination !== 'string' || !nodes.has(destination)) {
452	        throw new Error(`node ${node.id} points to an unknown destination`);
453	      }
454	    }
455	    return [node.then, node.else];
456	  }
457	  const next = node.next;
458	  if (Array.isArray(next)) {
459	    if (next.length === 0) {
460	      throw new Error(`node ${node.id}: next array must not be empty`);
461	    }
462	    const seen = new Set();
463	    for (const destination of next) {
464	      if (typeof destination !== 'string') {
465	        throw new Error(`node ${node.id}: next array entries must be node id strings`);
466	      }
467	      if (seen.has(destination)) {
468	        throw new Error(`node ${node.id}: duplicate destination ${destination}`);
469	      }
470	      seen.add(destination);
471	      if (!nodes.has(destination)) {
472	        throw new Error(`node ${node.id} points to an unknown destination`);
473	      }
474	    }
475	    return [...seen];
476	  }
477	  if (typeof next !== 'string' || !nodes.has(next)) {
478	    throw new Error(`node ${node.id} points to an unknown destination`);
479	  }
480	  return [next];
481	}
482	
483	// Resolves the explicit dependencies of a node. Dependencies only gate when a
484	// node may run; they never activate it. A missing dependsOn means no
485	// dependencies, and the entry node must not declare any.
486	function normalizeDependencies(node, nodes, entryId) {
487	  if (!Object.hasOwn(node, 'dependsOn') || node.dependsOn === undefined) return [];
488	  if (!Array.isArray(node.dependsOn)) {
489	    throw new Error(`node ${node.id}: dependsOn must be an array`);
490	  }
491	  const seen = new Set();
492	  for (const dependency of node.dependsOn) {
493	    if (typeof dependency !== 'string') {
494	      throw new Error(`node ${node.id}: dependsOn entries must be node id strings`);
495	    }
496	    if (seen.has(dependency)) {
497	      throw new Error(`node ${node.id}: duplicate dependency ${dependency}`);
498	    }
499	    seen.add(dependency);
500	    if (!nodes.has(dependency)) {
501	      throw new Error(`node ${node.id} depends on an unknown node`);
502	    }
503	    if (dependency === node.id) {
