  // The caller's own objects were never touched.
  assert.deepEqual(callerInput.amount, 10);
  assert.deepEqual(callerInput.nested, { v: 1 });
  assert.deepEqual([...new Uint8Array(callerInput.bytes)], [1, 1, 1, 1]);
});

