39	function assertMessageSharedMemoryError(error, nodeId = 'note') {
40	  assert.ok(error instanceof Error, 'a definition error (plain Error) is thrown/rejected');
41	  assert.ok(!(error instanceof TypeError), 'shared-memory messages are a definition error, not a TypeError');
42	  assert.match(error.message, new RegExp(`action node ${nodeId}: message contains shared memory`));
43	  assert.match(error.message, /SharedArrayBuffer/);
44	  assert.match(error.message, /independent copies cannot be guaranteed/);
