47	// Every message below retains shared memory in the content its structured
48	// clone actually saves.
49	function sharedMessages() {
50	  const cyclic = () => {
51	    const value = { label: 'self' };
52	    value.myself = value;
53	    value.shared = new SharedArrayBuffer(2);
54	    return value;
55	  };
56	  const aliased = () => {
57	    const shared = new SharedArrayBuffer(2);
58	    const holder = { buffer: shared };
59	    return { a: holder, b: holder, list: [shared] };
60	  };
61	  const causeIsNonEnumerable = () => {
62	    const error = new Error('wrap', { cause: new Uint8Array(new SharedArrayBuffer(2)) });
63	    // The Error constructor installs "cause" as a non-enumerable own
64	    // property; it must still count because the clone retains it.
65	    assert.equal(Object.getOwnPropertyDescriptor(error, 'cause').enumerable, false);
66	    return error;
67	  };
68	  return [
69	    () => new SharedArrayBuffer(4),
70	    () => new Uint8Array(new SharedArrayBuffer(4)),
71	    () => new Int32Array(new SharedArrayBuffer(8)),
72	    () => new Float64Array(new SharedArrayBuffer(8)),
73	    () => new BigInt64Array(new SharedArrayBuffer(8)),
74	    () => new DataView(new SharedArrayBuffer(4)),
75	    () => new Uint8Array(new SharedArrayBuffer(8), 2, 3),
76	    () => ({ inner: { bytes: new SharedArrayBuffer(4) } }),
77	    () => ({ list: [1, [2, new Uint8Array(new SharedArrayBuffer(4))]] }),
78	    () => [new SharedArrayBuffer(4)],
79	    () => new Map([['k', new SharedArrayBuffer(4)]]),
80	    () => new Map([[new SharedArrayBuffer(4), 'k']]),
81	    () => new Map([['k', { view: new DataView(new SharedArrayBuffer(4)) }]]),
82	    () => new Set([new SharedArrayBuffer(4)]),
83	    () => new Set([{ bytes: new Uint8Array(new SharedArrayBuffer(4)) }]),
84	    () => ({ table: new Map([[new Set([new SharedArrayBuffer(4)]), new DataView(new SharedArrayBuffer(4))]]) }),
85	    causeIsNonEnumerable,
86	    cyclic,
87	    aliased,
88	  ];
89	}
